import {Config, Field} from 'alinea'

export default Config.type('Kitchen sink', {
  fields: {
    ...Field.tabs(
      Field.tab('Basic fields', {
        fields: {
          title: Field.text('Text field'),
          path: Field.path('Path field', {
            help: 'Creates a slug of the value of another field'
          }),
          richText: Field.richText('Rich text field'),
          select: Field.select('Select field', {
            options: {
              a: 'Option a',
              b: 'Option b'
            }
          }),
          number: Field.number('Number field', {
            minValue: 0,
            maxValue: 10
          }),
          check: Field.check('Check field', {description: 'Check me please'}),
          date: Field.date('Date field', {width: 0.5}),
          time: Field.time('Time field', {width: 0.5}),
          code: Field.code('Code field')
        }
      }),
      Field.tab('Link fields', {
        fields: {
          externalLink: Field.url('External link'),
          entry: Field.entry('Internal link'),
          linkMultiple: Field.link.multiple('Mixed links, multiple'),
          image: Field.image('Image link'),
          file: Field.file('File link')
        }
      }),
      Field.tab('List fields', {
        fields: {
          list: Field.list('My list field', {
            schema: {
              Text: Config.type('Text', {
                fields: {
                  title: Field.text('Item title'),
                  text: Field.richText('Item body text')
                }
              }),
              Image: Config.type('Image', {
                fields: {
                  image: Field.image('Image')
                }
              })
            }
          })
        }
      }),
      Field.tab('Inline fields', {
        fields: {
          street: Field.text('Street', {width: 0.6, inline: true}),
          streetNr: Field.text('Number', {width: 0.2, inline: true}),
          box: Field.text('Box', {width: 0.2, inline: true}),
          zip: Field.text('Zipcode', {width: 0.2, inline: true}),
          city: Field.text('City', {width: 0.4, inline: true}),
          country: Field.text('Country', {width: 0.4, inline: true})
        }
      })
    )
  }
})

import {Field} from 'alinea'

Field.text('Discount code', {
  help: 'Uppercase letters and digits only',
  width: 0.5,
  required: true,
  validate(value) {
    if (!/^[A-Z0-9]*$/.test(value)) return 'Use uppercase letters and digits'
  }
})

import {Config, Field} from 'alinea'

export const Product = Config.document('Product', {
  fields: {
    // Translated per locale
    description: Field.richText('Description'),
    // The same in every locale
    price: Field.number('Price', {shared: true}),
    image: Field.image('Image', {shared: true})
  }
})

import {Config, Field} from 'alinea'

const linkType = Field.select('Link to', {
  initialValue: 'page',
  options: {page: 'A page', external: 'An external url'}
})

export const CallToAction = Config.type('Call to action', {
  fields: {
    label: Field.text('Label'),
    linkType,
    page: Config.track.options(Field.entry('Page'), get => ({
      hidden: get(linkType) !== 'page'
    })),
    url: Config.track.options(Field.url('Url'), get => ({
      hidden: get(linkType) !== 'external'
    }))
  }
})

import {Config, Field} from 'alinea'

const Example = Config.type('Conditional example', {
  fields: {
    textField: Field.text('Text field'),
    readOnly: Field.check('Make read-only'),
    hidden: Field.check('Hide field')
  }
})

Config.track.options(Example.textField, get => {
  const textField = get(Example.textField)
  const readOnly = get(Example.readOnly)
  const hidden = get(Example.hidden)
  return {
    readOnly,
    hidden,
    help: `Text has ${textField.length} characters`
  }
})

export default Example

import {Config, Field} from 'alinea'

export const Settings = Config.type('Settings', {
  fields: {
    title: Field.text('Site name'),
    ...Field.view(<hr />),
    analyticsId: Field.text('Analytics id', {help: 'Leave empty to disable'})
  }
})
